using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using Newtonsoft.Json;
public static class LightningNovaFrameEvents {
 static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
 static string Out=Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/LightningNova/V1.3");
 static Type utility,windowType;static EditorWindow window,focused;static bool created,background,paused;static List<GameObject> clones=new List<GameObject>(),demos=new List<GameObject>();static List<bool> active=new List<bool>();static List<object> reports=new List<object>();static int count=1,stage,attempts;static double begin;static ParticleSystem[] systems;
 static object Field(object obj,string name)=>obj.GetType().GetField(name,flags)?.GetValue(obj);
 static void Disable(){windowType.GetMethod("DisableFrameDebugger",flags).Invoke(window,null);EditorApplication.isPaused=false;}
 static void Setup(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();for(int i=0;i<count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/LightningNova/Prefabs/LightningNova_3D.prefab"));g.name="FrameProbe_"+i;g.transform.position=new Vector3(0,-.35f,0);g.transform.rotation=Quaternion.Euler(30,-22,0);clones.Add(g);}systems=clones.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>()).ToArray();stage=0;begin=Time.timeAsDouble;}
 static void Restart(){foreach(var p in systems){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Play(false);}begin=Time.timeAsDouble;stage=1;}
 static void Finish(string error=null){EditorApplication.update-=Tick;try{Disable();}catch{}foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);for(int i=0;i<demos.Count;i++)if(demos[i]!=null)demos[i].SetActive(active[i]);Application.runInBackground=background;EditorApplication.isPaused=paused;if(created&&window!=null)window.Close();if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"FrameDebuggerEvents.json"),JsonConvert.SerializeObject(new{error,method="Official FrameDebuggerWindow EnableFrameDebugger, current Profiler target; 1/8 real Play Mode instances at native age ~0.17; diagnostic capture isolated from timing",reports,limitation="Event metadata alone does not prove renderer merges; event details marked available only if native GetFrameEventData succeeded.",restored=true},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Play Mode stopped");return;}if(stage==0&&Time.timeAsDouble-begin>.8){Restart();return;}if(stage==1&&Time.timeAsDouble-begin>.17){EditorApplication.isPaused=true;windowType.GetMethod("EnableFrameDebugger",flags).Invoke(window,null);stage=2;begin=EditorApplication.timeSinceStartup;attempts=0;return;}
  if(stage==2&&EditorApplication.timeSinceStartup-begin>.7){var events=(Array)utility.GetMethod("GetFrameEvents",flags).Invoke(null,null);if((events==null||events.Length==0)&&attempts++<2){begin=EditorApplication.timeSinceStartup;return;}var list=new List<object>();int detailAttempts=0;if(events!=null)for(int i=0;i<events.Length;i++){var evt=events.GetValue(i);var obj=Field(evt,"m_Obj") as UnityEngine.Object;string type=Field(evt,"m_Type")?.ToString();if(type==null)continue;bool dataOk=false;object detail=null;if(obj!=null&&detailAttempts++<4){try{var dt=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerEventData");var data=Activator.CreateInstance(dt,true);dataOk=(bool)utility.GetMethod("GetFrameEventData",flags).Invoke(null,new[]{(object)i,data});if(dataOk)detail=new{shader=Field(data,"m_RealShaderName")?.ToString(),pass=Field(data,"m_PassName")?.ToString(),draws=Field(data,"m_DrawCallCount"),instances=Field(data,"m_InstanceCount"),vertices=Field(data,"m_VertexCount")};}catch{}}
   list.Add(new{index=i,type,obj=obj==null?null:obj.name,info=utility.GetMethod("GetFrameEventInfoName",flags).Invoke(null,new object[]{i})?.ToString(),dataOk,detail});}
   reports.Add(new{instances=count,totalEvents=events?.Length??0,events=list,liveParticles=systems.Sum(p=>p.particleCount)});Disable();if(count==1){count=8;Setup();}else Finish();}
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.productName!="VFXDemo")throw new Exception("Wrong state");utility=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerUtility");windowType=typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow");focused=EditorWindow.focusedWindow;background=Application.runInBackground;paused=EditorApplication.isPaused;Application.runInBackground=true;window=Resources.FindObjectsOfTypeAll(windowType).Cast<EditorWindow>().FirstOrDefault();created=window==null;if(created)window=EditorWindow.GetWindow(windowType);foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.name=="LightningNova_2D_Demo"||g.name=="LightningNova_3D_Demo")){demos.Add(root);active.Add(root.activeSelf);root.SetActive(false);}Setup();EditorApplication.update+=Tick;return "Bounded Frame Debugger capture scheduled.";}
}
